        let (Tracked(lock2x), handle2x) = self.locks[l2x].acquire_write();

        let mut i: usize = 0;
        while i < WIDTH
            invariant 0 <= i <= WIDTH, self.wf(),
                self.locks[l2x as int].inv(lock2x),
                row_store_wf(self.consts@, lock2x.rows[h2x as nat], h2x as nat),
