                forall |j| 0 <= j < WIDTH ==> (#[trigger] lock2x.rows[h2x as nat].token.value()[j] matches Some((k, _)) ==> k != key),
                forall |j| 0 <= j < i ==> (#[trigger] lock2x.rows[h2x as nat].token.value()[j].is_some()),
