    broadcast use group_imap_lemmas, group_seq_lemmas;
    assert forall |key2: Key| (#[trigger] post.frag[key2]).is_some() implies
        exists |r: Row, c: Col|
            0 <= r < HEIGHT && 0 <= c < WIDTH
                && (#[trigger] post.matrix[r][c]).is_some()
                && post.matrix[r][c].unwrap().0 == key2
    by {
        assert(key2 != key);
        assert(pre.frag[key2].is_some());
        let row2 = choose |r: Row| 0 <= r < HEIGHT &&
            exists |c: Col| 0 <= c < WIDTH &&
                (pre.matrix[r][c]).is_some() && pre.matrix[r][c].unwrap().0 == key2;
        let col2 = choose |c: Col| 0 <= c < WIDTH &&
            (pre.matrix[row2][c]).is_some() && pre.matrix[row2][c].unwrap().0 == key2;
        assert(0 <= row2 < HEIGHT);
        assert(0 <= col2 < WIDTH);
        assert(pre.matrix[row2][col2 as int].is_some());
        assert(pre.matrix[row2][col2 as int].unwrap().0 == key2);
        // (row2, col2) cannot be (row, col) since pre.matrix[row][col].unwrap().0 == key != key2
        assert(!(row2 == row && col2 == col)) by {
            if row2 == row && col2 == col {
                assert(pre.matrix[row][col as int].unwrap().0 == key2);
                // but pre.matrix[row][col].unwrap().0 == key (from transition precondition)
                assert(false);
            }
        };
        // post.matrix[row2][col2] == pre.matrix[row2][col2] since (row2, col2) != (row, col)
        assert(post.matrix[row2][col2 as int] == pre.matrix[row2][col2 as int]) by {
            if row2 == row {
                // col2 != col
                assert(col2 != col);
                // post.matrix[row] = pre.matrix[row].update(col, None)
                // seq_update_different fires: col2 != col
            }
            // if row2 != row, imap_insert_different fires
        };
        assert(post.matrix[row2][col2 as int].is_some());
        assert(post.matrix[row2][col2 as int].unwrap().0 == key2);
