#[inductive(swing)]
fn swing_inductive(pre: Self, post: Self, key: Key, row: Row, col: Col, row2: Row, col2: Col) {
    broadcast use group_imap_lemmas, group_seq_lemmas;
    assert(row != row2);
    assert forall |key3: Key| (#[trigger] post.frag[key3]).is_some() implies
        exists |r: Row, c: int|
            0 <= r < HEIGHT && 0 <= c < WIDTH
                && (#[trigger] post.matrix[r][c]).is_some()
                && post.matrix[r][c].unwrap().0 == key3
    by {
        // swing doesn't change frag
        assert(pre.frag[key3].is_some());
        let (row3, col3) = choose |r: Row, c: int|
            0 <= r < HEIGHT && 0 <= c < WIDTH
                && (#[trigger] pre.matrix[r][c]).is_some()
                && pre.matrix[r][c].unwrap().0 == key3;
        assert(0 <= row3 < HEIGHT);
        assert(0 <= col3 < WIDTH);
        assert(pre.matrix[row3][col3].is_some());
        assert(pre.matrix[row3][col3].unwrap().0 == key3);
        if row3 == row && col3 == col as int {
            // key3 == key, which is now at (row2, col2) in post
            assert(post.matrix[row2][col2 as int] == pre.matrix[row][col as int]);
            assert(post.matrix[row2][col2 as int].is_some());
            assert(post.matrix[row2][col2 as int].unwrap().0 == key3);
        } else if row3 == row2 && col3 == col2 as int {
            // pre.matrix[row2][col2] must be None (from swing precondition r2[col2].is_none())
            assert(pre.matrix[row2][col2 as int].is_none());
            assert(false);
        } else {
            // (row3, col3) is unchanged in post.matrix
            assert(post.matrix[row3][col3] == pre.matrix[row3][col3]) by {
                if row3 == row {
                    assert(col3 != col as int);
                } else if row3 == row2 {
                    assert(col3 != col2 as int);
                }
            };
            assert(post.matrix[row3][col3].is_some());
            assert(post.matrix[row3][col3].unwrap().0 == key3);
        }
    };
}

